package br.com.confirmacao.patient.application;import br.com.confirmacao.patient.domain.*;import br.com.confirmacao.patient.infrastructure.PatientRepository;import br.com.confirmacao.professional.application.ProfessionalNotFoundException;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.UUID;
@Service public class PatientService{private final PatientRepository patients;private final ProfessionalRepository professionals;public PatientService(PatientRepository p,ProfessionalRepository r){patients=p;professionals=r;}@Transactional public Patient create(UUID pid,String n,LocalDate b,String phone,String e,PreferredContactChannel c){var pro=professionals.findById(pid).orElseThrow(()->new ProfessionalNotFoundException(pid));if(patients.existsByProfessionalIdAndPhone(pid,norm(phone)))throw new PatientAlreadyExistsException();return patients.save(new Patient(pro,n,b,phone,e,c));}@Transactional(readOnly=true)public Page<Patient> findAll(UUID pid,Pageable p){return patients.findAllByProfessionalId(pid,p);}@Transactional(readOnly=true)public Patient findById(UUID pid,UUID id){return patients.findByIdAndProfessionalId(id,pid).orElseThrow(()->new PatientNotFoundException(id));}@Transactional public Patient update(UUID pid,UUID id,String n,LocalDate b,String ph,String e,PreferredContactChannel c){var x=findById(pid,id);if(patients.existsByProfessionalIdAndPhoneAndIdNot(pid,norm(ph),id))throw new PatientAlreadyExistsException();x.update(n,b,ph,e,c);return x;}@Transactional public void activate(UUID p,UUID i){findById(p,i).activate();}@Transactional public void deactivate(UUID p,UUID i){findById(p,i).deactivate();}@Transactional public Patient grantConsent(UUID p,UUID i){var x=findById(p,i);x.grantConsent();return x;}@Transactional public Patient revokeConsent(UUID p,UUID i){var x=findById(p,i);x.revokeConsent();return x;}private String norm(String v){return v==null?null:v.replaceAll("\\D","");}}
